    /**
     * Generates a random Pokemon team for the user.
     * Excludes Steel types and Pokemon with 625+ base stat totals.
     *
     * @param numberOfPokemon The number of Pokemon to generate.
     */
    public static void generatePokemon(int numberOfPokemon) {
        Random random = new Random();

        // Create a list excluding Pokemon of type STEEL, with baseStatTotals of 625+,
        // and after position 942 if gen9 is set to false.
        List<Pokemon> filteredPokemon = IntStream.range(0, Pokemon.allPokemon.size())
                .filter(index -> (gen9 || index < 942))
                .mapToObj(index -> Pokemon.allPokemon.get(index))
                .filter(pokemon -> !pokemon.type.contains(Type.STEEL) && pokemon.baseStatTotal < 625)
                .collect(Collectors.toList());

        if (filteredPokemon.isEmpty() || filteredPokemon.size() < numberOfPokemon) {
            System.out.println("Insufficient Pokémon available that meet the criteria.");
            return;
        }

        for (int i = 0; i < numberOfPokemon; i++) {
            int randomIndex = random.nextInt(filteredPokemon.size());
            Pokemon pokemon = filteredPokemon.get(randomIndex);

            // Remove the chosen Pokémon from the list
            filteredPokemon.remove(randomIndex);

            System.out.println(pokemon.name + " @ " + capitalize(pokemon.heldItem.name().toLowerCase().replace("_", " ")));
            System.out.println("Ability: " + capitalize(pokemon.ability.name().toLowerCase().replace("_", " ")));
            System.out.println("Level: " + pokemon.level);

            if (pokemon.shiny) {
                System.out.println("Shiny: Yes");
            }

            System.out.println("Tera Type: " + capitalize(pokemon.teraType.name().toLowerCase()));
            System.out.println("EVs: " + pokemon.evHP + " HP / " + pokemon.evAtk + " Atk / " + pokemon.evDef
                    + " Def / " + pokemon.evSpAtk + " SpA / " + pokemon.evSpDef + " SpD / " + pokemon.evSpeed + " Spe");
            System.out.println(capitalize(pokemon.nature.name()) + " Nature");
            System.out.println("- Metronome");
            System.out.println();
        }
    }

    /**
     * Capitalizes the first letter of each word.
     *
     * @param input The string to capitalize.
     * @return The capitalized string.
     */
    public static String capitalize(String input) {
        StringBuilder result = new StringBuilder();
        boolean capitalizeNext = true;  // Flag to determine if the next char should be capitalized

        for (char c : input.toCharArray()) {
            if (Character.isWhitespace(c)) {
                capitalizeNext = true;
            } else if (capitalizeNext) {
                c = Character.toUpperCase(c);
                capitalizeNext = false;
            } else {
                c = Character.toLowerCase(c);
            }
            result.append(c);
        }

        return result.toString();
    }
